using System.Net.Http.Headers;
using System.Text;
using System.Text.Json;
public class RaceDayApiClient {
 private readonly IHttpClientFactory _factory; private readonly IHttpContextAccessor _accessor; private static readonly JsonSerializerOptions Json = new(){PropertyNameCaseInsensitive=true};
 public RaceDayApiClient(IHttpClientFactory f,IHttpContextAccessor a){_factory=f;_accessor=a;}
 private HttpClient Client(){var c=_factory.CreateClient("RaceDayApi"); var cookie=_accessor.HttpContext?.Session.GetString("ApiCookie"); if(!string.IsNullOrWhiteSpace(cookie)) c.DefaultRequestHeaders.Add("Cookie",cookie); return c;}
 public async Task<(T? Data,string Error,bool Ok)> Send<T>(HttpMethod method,string path,object? body=null){try{using var req=new HttpRequestMessage(method,path); if(body!=null) req.Content=new StringContent(JsonSerializer.Serialize(body),Encoding.UTF8,"application/json"); using var res=await Client().SendAsync(req); var raw=await res.Content.ReadAsStringAsync(); if(!res.IsSuccessStatusCode)return(default,ExtractError(raw,$"API returned {(int)res.StatusCode}"),false); if(typeof(T)==typeof(string))return((T)(object)raw,"",true); if(string.IsNullOrWhiteSpace(raw))return(default,"",true); return(JsonSerializer.Deserialize<T>(raw,Json),"",true);}catch(Exception ex){return(default,"Could not connect to RaceDay API. Check Api:BaseUrl. "+ex.Message,false);}}
 public async Task<(UserDto? User,string Error)> Login(string email,string password){try{var c=Client();using var r=await c.PostAsync("api/auth/login",new StringContent(JsonSerializer.Serialize(new{email,password}),Encoding.UTF8,"application/json"));var raw=await r.Content.ReadAsStringAsync();if(!r.IsSuccessStatusCode)return(null,ExtractError(raw,"Login failed."));var cookie=r.Headers.TryGetValues("Set-Cookie",out var vals)?vals.FirstOrDefault()?.Split(';')[0]:null;if(cookie!=null)_accessor.HttpContext!.Session.SetString("ApiCookie",cookie);return(JsonSerializer.Deserialize<UserDto>(raw,Json),"");}catch(Exception ex){return(null,"API connection failed: "+ex.Message);}}
 public async Task<(bool Ok,string Error)> Upload(string path,IFormFile file){try{using var form=new MultipartFormDataContent();await using var s=file.OpenReadStream();var part=new StreamContent(s);part.Headers.ContentType=new MediaTypeHeaderValue(file.ContentType);form.Add(part,"file",Path.GetFileName(file.FileName));using var res=await Client().PutAsync(path,form);var raw=await res.Content.ReadAsStringAsync();return(res.IsSuccessStatusCode,"Upload failed: "+ExtractError(raw,"Check that the API accepts this image."));}catch(Exception ex){return(false,ex.Message);}}
 public async Task<(bool Ok,string Error)> UploadPost(string path,IFormFile file){try{using var form=new MultipartFormDataContent();await using var s=file.OpenReadStream();var part=new StreamContent(s);part.Headers.ContentType=new MediaTypeHeaderValue(file.ContentType);form.Add(part,"file",Path.GetFileName(file.FileName));using var res=await Client().PostAsync(path,form);var raw=await res.Content.ReadAsStringAsync();return(res.IsSuccessStatusCode,"Upload failed: "+ExtractError(raw,"Check image upload endpoint."));}catch(Exception ex){return(false,ex.Message);}}
 public static string ExtractError(string raw,string fallback){try{using var d=JsonDocument.Parse(raw);if(d.RootElement.TryGetProperty("message",out var m))return m.GetString()??fallback;if(d.RootElement.TryGetProperty("title",out var t))return t.GetString()??fallback;}catch{}return string.IsNullOrWhiteSpace(raw)?fallback:raw;}
}
